namespace LeoLauncher;
sealed partial class TodoStore
{
    public void Rename(string id,string title,bool future=false){var task=Find(id);title=Title(title);Commit(records.Select(t=>t.Id==id?t with{Title=title,MatchTitleManaged=t.MatchId==null&&t.MatchTitleManaged}:future&&task.SeriesId!=null&&(t.Id==task.SeriesId||t.SeriesId==task.SeriesId&&t.OccurrenceDay>=task.OccurrenceDay&&t.Completed==null&&!t.Deleted)?t with{Title=title}:t).ToList());}
    public void MoveTo(string id,DateOnly date){var task=Find(id);if(task.Day==date)return;Commit(records.Select(t=>t.Id==id?t with{Day=date,Reminder=Shift(task.Reminder,task.Day,date),Notified=null,SnoozedUntil=null,MatchFollowSchedule=task.MatchId==null&&task.MatchFollowSchedule,MatchReminderManaged=task.MatchId==null&&task.MatchReminderManaged}:t).ToList());}
    public void Snooze(string id,int minutes,DateTimeOffset now){if(minutes is not(10 or 60))throw new ArgumentException("请选择10分钟或1小时");var task=Find(id);if(task.Completed!=null)throw new ArgumentException("事项已完成");var time=now.AddMinutes(minutes);Commit(records.Select(t=>t.Id==id?t with{Reminder=time,SnoozedUntil=time,Notified=null}:t).ToList());}
    public int SyncMatches(IEnumerable<FootballMatch> matches,DateTimeOffset observed){var map=matches.Where(m=>!string.IsNullOrWhiteSpace(m.Id)).GroupBy(m=>"espn:"+m.Id).ToDictionary(g=>g.Key,g=>g.Last());int changes=0;var next=records.Select(task=>{if(task.Repeat!=null||task.Deleted||task.Completed!=null||task.MatchId==null||!task.MatchFollowSchedule||!map.TryGetValue(task.MatchId,out var match)||task.MatchUpdated>observed)return task;
        bool cancel=match.Status.Contains("cancel",StringComparison.OrdinalIgnoreCase)||match.Status.Contains("abandon",StringComparison.OrdinalIgnoreCase);bool postponed=!match.TimeKnown||match.Status.Contains("postpon",StringComparison.OrdinalIgnoreCase)||match.Status.Contains("TBD",StringComparison.OrdinalIgnoreCase)||match.Status.Contains("TBA",StringComparison.OrdinalIgnoreCase);string status=cancel?"cancelled":match.State=="post"?"finished":postponed?"postponed":match.State=="in"?"live":"scheduled";var current=task with{MatchUpdated=observed,MatchStatus=status};
        if(cancel||postponed||status=="finished"){if(task.MatchReminderManaged)current=current with{Reminder=null,SnoozedUntil=null,Notified=null};}
        else if(status=="scheduled"){bool changed=task.MatchKickoff!=match.Kickoff||task.MatchStatus is "cancelled" or "postponed" or "finished";current=current with{MatchKickoff=match.Kickoff,Day=DateOnly.FromDateTime(match.Kickoff.LocalDateTime)};if(task.MatchReminderManaged&&changed&&!(task.SnoozedUntil>observed)){var reminder=match.Kickoff.AddMinutes(-10);current=current with{Reminder=reminder<observed?observed:reminder,Notified=null,SnoozedUntil=null};}}
        else if(status=="live"&&task.MatchReminderManaged)current=current with{Reminder=null,SnoozedUntil=null};
        if(task.MatchTitleManaged)current=current with{Title=Title("看球 · "+FootballFeed.Name(match.Home)+" vs "+FootballFeed.Name(match.Away))};if(current!=task){if(current.Day!=task.Day||current.Reminder!=task.Reminder||current.MatchStatus!=task.MatchStatus)changes++;return current;}return task;}).ToList();if(!next.SequenceEqual(records))Commit(next);return changes;}
}
sealed partial class TodoStore
{
    public void HydrateMatchMetadata(IEnumerable<FootballMatch> cache,DateTimeOffset observed){var map=cache.GroupBy(m=>"espn:"+m.Id).ToDictionary(g=>g.Key,g=>g.Last());bool changed=false;var next=records.Select(t=>{if(t.MatchId==null||t.MatchKickoff!=null||!map.TryGetValue(t.MatchId,out var m))return t;changed=true;return t with{MatchKickoff=m.Kickoff,MatchFollowSchedule=t.Day==DateOnly.FromDateTime(m.Kickoff.LocalDateTime),MatchReminderManaged=t.Reminder==m.Kickoff.AddMinutes(-10),MatchUpdated=observed};}).ToList();if(changed)Commit(next);}
    public void FollowMatch(string id){var task=Find(id);if(task.MatchId==null||task.MatchKickoff==null)throw new InvalidOperationException("请先联网更新比赛时间");var reminder=task.MatchKickoff.Value.AddMinutes(-10);Commit(records.Select(t=>t.Id==id?t with{Day=DateOnly.FromDateTime(task.MatchKickoff.Value.LocalDateTime),MatchFollowSchedule=true,MatchReminderManaged=true,Reminder=task.MatchStatus is "cancelled" or "postponed" or "finished"?null:reminder< DateTimeOffset.Now?DateTimeOffset.Now:reminder,Notified=null,SnoozedUntil=null}:t).ToList());}
}
